<template><section class="admin-data-page"><header class="admin-page-head"><div><p>CONTENT</p><h1>공지사항 관리</h1><span>고객에게 안내할 공지를 작성하고 게시 내용을 관리합니다.</span></div><div class="admin-count"><strong>{{ filteredNotices.length }}</strong><span>건</span></div></header>
<div class="content-layout"><aside class="editor-card"><div class="editor-head"><div><small>{{ isEditing?'EDIT NOTICE':'NEW NOTICE' }}</small><h2>{{ isEditing?'공지사항 수정':'새 공지 작성' }}</h2></div><button v-if="isEditing" class="admin-btn small ghost" @click="resetForm">취소</button></div><form @submit.prevent="submitNotice"><label><span>제목 *</span><input v-model.trim="form.title" maxlength="100" placeholder="공지 제목" required></label><label><span>요약</span><textarea v-model.trim="form.summary" rows="3" maxlength="250" placeholder="목록에 표시할 짧은 설명"></textarea><small>{{ form.summary.length }}/250</small></label><label><span>본문 *</span><textarea v-model.trim="form.content" rows="11" placeholder="공지 내용을 입력하세요." required></textarea></label><label><span>게시일 *</span><input v-model="form.date" type="date" required></label><button class="admin-btn primary editor-submit" :disabled="saving">{{ saving?'저장 중':isEditing?'수정 내용 저장':'공지 등록' }}</button></form></aside>
<div class="admin-table-card"><div class="admin-table-toolbar"><div><strong>공지 목록</strong><span>최신 공지부터 표시됩니다.</span></div><label class="content-search"><i class="fa-solid fa-magnifying-glass"></i><input v-model.trim="keyword" type="search" placeholder="제목 검색"></label></div><div v-if="error" class="admin-state error"><i class="fa-solid fa-circle-exclamation"></i><p>{{ error }}</p><button class="admin-btn ghost" @click="fetchNotices">다시 시도</button></div><div v-else class="admin-table-scroll"><table class="admin-table"><thead><tr><th>번호</th><th>제목</th><th>요약</th><th>게시일</th><th>관리</th></tr></thead><tbody><tr v-if="loading"><td colspan="5"><div class="admin-state compact"><i class="fa-solid fa-spinner fa-spin"></i><p>공지사항을 불러오는 중입니다.</p></div></td></tr><tr v-else-if="!filteredNotices.length"><td colspan="5"><div class="admin-state compact"><i class="fa-regular fa-folder-open"></i><p>등록된 공지가 없습니다.</p></div></td></tr><tr v-for="(notice,index) in filteredNotices" :key="notice._id" :class="{selected:form._id===notice._id}"><td>{{ filteredNotices.length-index }}</td><td class="notice-title"><strong>{{ notice.title }}</strong></td><td class="notice-summary">{{ notice.summary||'-' }}</td><td>{{ formatDate(notice.date) }}</td><td><div class="row-actions"><button class="admin-btn small ghost" @click="editNotice(notice)">수정</button><button class="admin-btn small danger" :disabled="deletingId===notice._id" @click="deleteNotice(notice)">{{ deletingId===notice._id?'삭제 중':'삭제' }}</button></div></td></tr></tbody></table></div></div></div></section></template>
<script setup>import{computed,onMounted,ref}from"vue";import NoticeService from"@/api/NoticeService";import{getStoredToken}from"@/utils/storage";const today=()=>new Date().toISOString().slice(0,10),emptyForm=()=>({_id:null,title:"",summary:"",content:"",date:today()});const noticeList=ref([]),form=ref(emptyForm()),isEditing=ref(false),keyword=ref(""),loading=ref(false),saving=ref(false),deletingId=ref(""),error=ref("");const filteredNotices=computed(()=>noticeList.value.filter(n=>(n.title||"").toLowerCase().includes(keyword.value.toLowerCase())));const formatDate=value=>{if(!value)return"-";const d=new Date(value);return Number.isNaN(d.getTime())?value:d.toLocaleDateString("ko-KR")};async function fetchNotices(){loading.value=true;error.value="";try{const{data}=await NoticeService.getNoticeList({page:1,size:1000},getStoredToken());noticeList.value=(data.notices||[]).sort((a,b)=>new Date(b.date)-new Date(a.date))}catch(err){console.error("공지 조회 실패:",err);error.value="공지사항을 불러오지 못했습니다."}finally{loading.value=false}}async function submitNotice(){if(!form.value.title||!form.value.content||!form.value.date)return alert("제목, 본문, 게시일을 입력해 주세요.");saving.value=true;const payload={title:form.value.title,summary:form.value.summary,content:form.value.content,date:form.value.date};try{isEditing.value?await NoticeService.updateNotice(form.value._id,payload,getStoredToken()):await NoticeService.createNotice(payload,getStoredToken());alert(isEditing.value?"공지사항이 수정되었습니다.":"공지사항이 등록되었습니다.");resetForm();await fetchNotices()}catch(err){console.error("공지 저장 실패:",err);alert(err.response?.data?.message||"공지사항을 저장하지 못했습니다.")}finally{saving.value=false}}function editNotice(notice){form.value={_id:notice._id,title:notice.title||"",summary:notice.summary||"",content:notice.content||"",date:String(notice.date||today()).slice(0,10)};isEditing.value=true;window.scrollTo({top:0,behavior:"smooth"})}function resetForm(){form.value=emptyForm();isEditing.value=false}async function deleteNotice(notice){if(!confirm(`'${notice.title}' 공지를 삭제하시겠습니까?`))return;deletingId.value=notice._id;try{await NoticeService.deleteNotice(notice._id,getStoredToken());if(form.value._id===notice._id)resetForm();await fetchNotices()}catch(err){console.error("공지 삭제 실패:",err);alert("공지사항을 삭제하지 못했습니다.")}finally{deletingId.value=""}}onMounted(fetchNotices);</script>
<style scoped>.content-layout{display:grid;grid-template-columns:minmax(310px,390px) minmax(0,1fr);gap:18px;align-items:start}.editor-card{padding:20px;border:1px solid #e3dcda;background:#fff}.editor-head{display:flex;justify-content:space-between;margin-bottom:18px}.editor-head small{color:#aa7c87;font-size:.57rem;font-weight:800;letter-spacing:.16em}.editor-head h2{margin:4px 0 0;font-family:Georgia,"Noto Serif KR",serif;font-size:1.25rem;font-weight:400}.editor-card form,.editor-card label{display:grid;gap:7px}.editor-card form{gap:13px}.editor-card label>span{font-size:.65rem;font-weight:700}.editor-card input,.editor-card textarea{padding:10px;border:1px solid #ddd4d1;outline:none;font:inherit;font-size:.7rem;resize:vertical}.editor-card label small{color:#9a9094;font-size:.58rem;text-align:right}.editor-submit{width:100%}.content-search{height:39px;display:flex;align-items:center;gap:7px;padding:0 10px;border:1px solid #ddd4d1}.content-search input{width:160px;border:0;outline:0}.notice-title{min-width:170px}.notice-summary{min-width:220px;max-width:340px;white-space:normal}.row-actions{display:flex;gap:6px}.admin-table tr.selected{background:#faf3f5}@media(max-width:1050px){.content-layout{grid-template-columns:1fr}}@media(max-width:600px){.content-search{width:100%}.content-search input{width:100%}}</style>
